const bankFields=[['unit','תהליך, מוצר, יחידה וישות בקבוצה'],['exposure','חשיפה — יתרות, עסקאות, לקוחות ומערכות'],['likelihood','תקופת הסתברות, תדירות אירועים ומגמה'],['impact','הפסד, פגיעה בלקוחות, השבתה והשפעה על הון ונזילות'],['controls','בקרות מניעה, גילוי, תגובה והתאוששות'],['effectiveness','אפקטיביות וראיות לבדיקה'],['appetite','תיאבון ומגבלות שאושרו'],['incidents','הפסדים, כמעט־אירועים, תלונות וממצאים'],['stress','תרחיש קיצון והשפעות משולבות'],['dependencies','תלות באשראי, נזילות, מוניטין וסיכונים אחרים'],['owner','בעל הסיכון'],['action','תוכנית טיפול ורמת יעד'],['budget','תקציב טיפול'],['deadline','מועד טיפול'],['kri','מדדי התרעה וספים'],['assumptions','הנחות, איכות נתונים ואי־ודאות'],['updated','מועד עדכון'],['lastAudit','מועד ביקורת אחרונה'],['findings','ממצאים פתוחים'],['changes','שינויים במערכות ובמוצרים'],['supervision','דרישות פיקוח ומשימות נדרשות'],['assurance','היקף, מועד וראיות לבדיקות פונקציות הבקרה'],['staff','כישורים ומשאבים נדרשים לביקורת'],['auditReason','נימוק לתעדוף ולתדירות הביקורת']];
const bankContext={legal:'טרם נבדק',regulated:'טרם נבדק',cro:'',appetiteRef:'',scope:'',method:'',approval:''};
